rcore 1;
package `colors` version "1";
metamodel "urn:intersect:xtext:enum-composition:1" prefix `colors` {
  class `Model` {
    attr `shade`: external "#//@eClassifiers.1" [0,1];
  }
  enum `Shade` {
    `Red` = 1 literal "red";
    `Blue` = 2 literal "blue";
  }
  enum `OtherShade` {
    `Red` = 1 literal "red";
    `Blue` = 2 literal "blue";
  }
}
